                  @onchange="e => UpdateEntry(description: e.Value?.ToString() ?? string.Empty)"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task UpdateEntry(
        string? company = null,
        string? title = null,
        DateTime? startDate = null,
        DateTime? endDate = null,
        bool? isCurrent = null,
        string? description = null)
    {
        var updated = Entry with
        {
            Company = company ?? Entry.Company,
            Title = title ?? Entry.Title,
            StartDate = startDate ?? Entry.StartDate,
            EndDate = isCurrent == true ? null : (endDate ?? Entry.EndDate),
            IsCurrent = isCurrent ?? Entry.IsCurrent,
            Description = description ?? Entry.Description
        };
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        await UpdateEntry(isCurrent: isCurrent, endDate: isCurrent ? null : Entry.EndDate);
    }
}
"}

