@namespace sv_e7beb5694c744bde8e603ba428204f86.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea class="form-control cover-letter-textarea" rows="12"
                  maxlength="2000"
                  @bind="CoverLetterText"
                  @bind:event="oninput"></textarea>
        <div class="character-count @(CoverLetterText.Length > 1800 ? "warning" : "")">
            @CoverLetterText.Length / 2000 characters
        </div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string CoverLetterText { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage { get; set; }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ErrorMessage = "Please write a cover letter before proceeding.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetterText);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

