    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #555;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.character-count {
    text-align: right;
    font-size: 0.8rem;
    color: #757575;
    margin-top: 0.25rem;
}

.character-count.warning {
    color: #e65100;
    font-weight: 500;
}

/* Review Step */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
